import{_ as t,o as a,c as e,ag as r}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/board/export-download-menu.png",i="/docs/images/board/export-miro-dialog.png",g=JSON.parse('{"title":"Export and import a board","description":"Download a board or a selection as a PNG or PDF, and import an existing Miro board as a new board.","frontmatter":{"title":"Export and import a board","description":"Download a board or a selection as a PNG or PDF, and import an existing Miro board as a new board.","type":"how-to"},"headers":[],"relativePath":"board/export-and-import.md","filePath":"board/export-and-import.md"}'),d={name:"board/export-and-import.md"};function s(l,o,h,c,p,m){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="export-and-import-a-board" tabindex="-1">Export and import a board <a class="header-anchor" href="#export-and-import-a-board" aria-label="Permalink to &quot;Export and import a board&quot;">​</a></h1><p>Download a board or a selection as a PNG or PDF, and import an existing Miro board as a new board.</p><h2 id="download-a-board" tabindex="-1">Download a board <a class="header-anchor" href="#download-a-board" aria-label="Permalink to &quot;Download a board&quot;">​</a></h2><ol><li>Open the board.</li><li>Click <strong>Download</strong> (the download icon) in the top-right corner of the canvas.</li><li>Select <strong>Download as PNG</strong> or <strong>Download as PDF</strong>.</li></ol><p>The file is named after the board and covers everything on it, with a small margin. A PDF is one page sized to the content. Anyone who can open the board can download it, viewers included.</p><p><img src="'+n+'" alt="Download menu open in the top-right corner of the canvas with PNG and PDF options for the whole board or the selection"></p><h3 id="download-only-a-selection" tabindex="-1">Download only a selection <a class="header-anchor" href="#download-only-a-selection" aria-label="Permalink to &quot;Download only a selection&quot;">​</a></h3><ol><li>Select the items you want. To export one section, select the section.</li><li>Click <strong>Download</strong> and select <strong>Download selection as PNG</strong> or <strong>Download selection as PDF</strong>.</li></ol><h2 id="import-a-miro-board" tabindex="-1">Import a Miro board <a class="header-anchor" href="#import-a-miro-board" aria-label="Permalink to &quot;Import a Miro board&quot;">​</a></h2><p>The import creates a new board in your workspace from a Miro board.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need a Miro access token that can read the board. The token is used for this one import and is never stored.</li><li>Start the import from a workspace&#39;s document list, not from the all-workspaces list.</li></ul></div><ol><li>In your workspace, click <strong>New</strong>, then select <strong>Import from Miro…</strong>.</li><li>Paste the token under <strong>Access token</strong>.</li><li>Paste the board&#39;s address under <strong>Board URL</strong>, for example <code>https://miro.com/app/board/uXjVOD50NUI=/</code>.</li><li>Click <strong>Import</strong>.</li></ol><p>The import continues in the background, and its progress shows in the uploads panel. When it finishes, the panel lists anything that didn&#39;t come across.</p><p><img src="'+i+'" alt="Import a Miro board dialog with the Access token and Board URL fields"></p><h3 id="what-comes-across" tabindex="-1">What comes across <a class="header-anchor" href="#what-comes-across" aria-label="Permalink to &quot;What comes across&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Miro item</th><th>On the board</th></tr></thead><tbody><tr><td>Sticky notes</td><td>Sticky notes</td></tr><tr><td>Cards and app cards</td><td>Rounded rectangles with the card&#39;s title and description</td></tr><tr><td>Shapes</td><td>Shapes. An unrecognized shape becomes a rectangle.</td></tr><tr><td>Text</td><td>Text boxes</td></tr><tr><td>Images</td><td>Images, copied into your workspace</td></tr><tr><td>Connectors</td><td>Connectors, when both ends are attached to items that were imported</td></tr><tr><td>Frames</td><td><a href="/docs/board/sections.html">Sections</a></td></tr></tbody></table><p>Other item types, such as embeds, are skipped and listed in the summary.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>A very large board is scaled down in the file to stay within size limits.</li><li>Items inside a hidden section are left out of a download.</li><li>Stamps, vote dots, and comment pins are not included in a download.</li><li>An empty board can&#39;t be downloaded. See <a href="#troubleshooting">Troubleshooting</a>.</li><li>One Miro import brings in up to 10,000 items and 100 images, up to 64 MB of images in total. The summary says when a board went over a limit.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="the-board-is-empty-—-nothing-to-export" tabindex="-1">The board is empty — nothing to export. <a class="header-anchor" href="#the-board-is-empty-—-nothing-to-export" aria-label="Permalink to &quot;The board is empty — nothing to export.&quot;">​</a></h3><p><strong>What it means:</strong> the board, or the part you selected, has nothing to put in the file.</p><p><strong>Try this:</strong> add something to the board, or select items that aren&#39;t inside a hidden section.</p><h3 id="couldn-t-export-the-board-try-again" tabindex="-1">Couldn&#39;t export the board. Try again. <a class="header-anchor" href="#couldn-t-export-the-board-try-again" aria-label="Permalink to &quot;Couldn&#39;t export the board. Try again.&quot;">​</a></h3><p><strong>What it means:</strong> the file couldn&#39;t be created.</p><p><strong>Try this:</strong></p><ol><li>Try again.</li><li>Reload the page, then download again.</li><li>If the board is very large, download a selection instead.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/files/import-export.html">Import and export</a> for every document type and format.</li><li><a href="/docs/board/sections.html">Sections</a> to group what you want to export.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to give people a link instead of a file.</li></ul>',29)])])}const u=t(d,[["render",s]]);export{g as __pageData,u as default};
